};






/**************************************************************************
 * [4] Callback 
 **************************************************************************/
scwin.sbm_selectAPRAPM8100R01_submitdone = function(e) {
    let cnt = dlt_out.getTotalRow();
	if(cnt > 0){
        spn_currRow.setValue(cnt);
        spn_totalRow.setValue(cnt);
    }else{
        spn_currRow.setValue("0");
        spn_totalRow.setValue("0");
    }

    //grid가 binding된 상태에서 callback에서 datalist값을  변경할 경우 병합이 제대로 안됨. dlt_out2로 대체
    dlt_out2.setBroadcast(false);
    dlt_out2.removeAll();
    for(let i=0; i<cnt; i++) {
	    //debugger;
	    let rowData = dlt_out.getRowJSON(i);

        /*************************
        * freight
        *************************/
        rowData.CMFTYP = (rowData.CMFTYP==""? "-": rowData.CMFTYP); //type
        //freight : bltype c,b
        if(rowData.CMFCTYPCB == ""){//cur
            rowData.CMFCTYPCB = "-";
	        rowData.CMFBLPDCB = (rowData.CMFBLPDCB==""? "-": rowData.CMFBLPDCB+ "%");
            rowData.CMFBLCLCB = (rowData.CMFBLCLCB==""? "-": rowData.CMFBLCLCB+ "%");
            rowData.CMFBDPDCB = (rowData.CMFBDPDCB==""? "-": rowData.CMFBDPDCB+ "%");
            rowData.CMFBDCLCB = (rowData.CMFBDCLCB==""? "-": rowData.CMFBDCLCB+ "%");
        } else {
            //rowData.CMFCTYPCB = rowData.CMFCTYPCB;
            rowData.CMFBLPDCB = (rowData.CMFBLPDCB==""? "-": rowData.CMFBLPDCB);
            rowData.CMFBLCLCB = (rowData.CMFBLCLCB==""? "-": rowData.CMFBLCLCB);
            rowData.CMFBDPDCB = (rowData.CMFBDPDCB==""? "-": rowData.CMFBDPDCB);
            rowData.CMFBDCLCB = (rowData.CMFBDCLCB==""? "-": rowData.CMFBDCLCB);
        }
        rowData.CMFMINCB = (rowData.CMFMINCB==""? "-": rowData.CMFMINCB);//m/m
        //freight : bltype f
        if(rowData.CMFCTYPF == ""){//cur
            rowData.CMFCTYPF = "-";
            rowData.CMFBLPDF = (rowData.CMFBLPDF==""? "-": rowData.CMFBLPDF+ "%");
            rowData.CMFBLCLF = (rowData.CMFBLCLF==""? "-": rowData.CMFBLCLF+ "%");
            rowData.CMFBDPDF = (rowData.CMFBDPDF==""? "-": rowData.CMFBDPDF+ "%");
            rowData.CMFBDCLF = (rowData.CMFBDCLF==""? "-": rowData.CMFBDCLF+ "%");
        } else {
            rowData.CMFBLPDF = (rowData.CMFBLPDF==""? "-": rowData.CMFBLPDF);
            rowData.CMFBLCLF = (rowData.CMFBLCLF==""? "-": rowData.CMFBLCLF);
            rowData.CMFBDPDF = (rowData.CMFBDPDF==""? "-": rowData.CMFBDPDF);
            rowData.CMFBDCLF = (rowData.CMFBDCLF==""? "-": rowData.CMFBDCLF);
        }
        rowData.CMFMINCF = (rowData.CMFMINCF==""? "-": rowData.CMFMINCF);//m/m

        /*************************
        * cntr 
        *************************/
        rowData.CMHTYPA = (rowData.CMHTYPA==""? "-": rowData.CMHTYPA);
        rowData.CMHOPR = (rowData.CMHOPR==""? "-": rowData.CMHOPR);
        rowData.CMHCUR = (rowData.CMHCUR==""? "-": rowData.CMHCUR);
        //bl type : c

        /*************************
        * dem/det , soc 
        *************************/
        rowData.DEMDETLPD = (rowData.DEMDETLPD==""? "-": rowData.DEMDETLPD+ "%");
        rowData.DEMDETDPD = (rowData.DEMDETDPD==""? "-": rowData.DEMDETDPD+ "%");
        rowData.SOCTMLLPD = (rowData.SOCTMLLPD==""? "-": rowData.SOCTMLLPD+ "%");
        rowData.SOCTMLDPD = (rowData.SOCTMLDPD==""? "-": rowData.SOCTMLDPD+ "%");
        /*************************
        * husbanding
        *************************/
        rowData.CMHUSOPR = (rowData.CMHUSOPR==""? "-": rowData.CMHUSOPR);
        rowData.CMHUSKND = (rowData.CMHUSKND==""? "-": rowData.CMHUSKND);
        rowData.CMHUSCUR = (rowData.CMHUSCUR==""? "-": rowData.CMHUSCUR);
        //rowData.CMHUSRAT = (rowData.CMHUSRAT==""? "-": numLib.addComma(rowData.CMHUSRAT));

        /*************************
        * others
        *************************/
        rowData.CMOITM = (rowData.CMOITM==""? "-": rowData.CMOITM);
        rowData.CMOKIND = (rowData.CMOKIND==""? "-": rowData.CMOKIND);
        rowData.CMOCUR = (rowData.CMOCUR==""? "-": rowData.CMOCUR);

        /*************************
        * intermodal
        *************************/
        rowData.CMLTYPA = (rowData.CMLTYPA==""? "-": rowData.CMLTYPA);
        rowData.CMLCUR = (rowData.CMLCUR==""? "-": rowData.CMLCUR);
//        rowData.CML20F = (rowData.CML20F==""? "-": numLib.addComma(rowData.CML20F));
//        rowData.CML20E = (rowData.CML20E==""? "-": numLib.addComma(rowData.CML20E));
//        rowData.CML40F = (rowData.CML40F==""? "-": numLib.addComma(rowData.CML40F));
//        rowData.CML40E = (rowData.CML40E==""? "-": numLib.addComma(rowData.CML40E));
//        rowData.CML4HF = (rowData.CML4HF==""? "-": numLib.addComma(rowData.CML4HF));
//        rowData.CML4HE = (rowData.CML4HE==""? "-": numLib.addComma(rowData.CML4HE));
//        rowData.CML45F = (rowData.CML45F==""? "-": numLib.addComma(rowData.CML45F));
//        rowData.CML45E = (rowData.CML45E==""? "-": numLib.addComma(rowData.CML45E));

        dlt_out2.setRowJSON(i, rowData, false);
    }
    dlt_out2.setBroadcast(true, true);
    //debugger;
};




/**************************************************************************
 * 기능 : 버튼 선택시 밸리데이션 처리
 **************************************************************************/
scwin.ff_searchValidation = function(type) {

	var rtn = "true";
	if(type == "ALL" || strLib.isEmpty(type)){


		if( dma_inp.get("INPTM1") == "" || dma_inp.get("INPTM2") == ""){
			if( dma_inp.get("INPTM1") == ""){
				ica_inptm1.setStyle("background", "Yellow");

			}

			if( dma_inp.get("INPTM2") == ""){
				ica_inptm2.setStyle("background", "Yellow");

			}

			com.alert(com.getMsg("COM00000",["Apply date"])); //{0} Is Mandatory.
			//ica_inptm1.focus();
			rtn = "false";
		}
		else{
			ica_inptm1.setStyle("background", "");
			ica_inptm2.setStyle("background", "");
		}
	 } 

	return rtn;


}

/* 데이터 많을때(1000이상) 그리드 스크롤이 너무 느려짐. 사용불가.
scwin.setPerNumFrC = function(data, formattedData, rowIndex, colIndex){
    let cur = dlt_out.getCellData(rowIndex, "CMFCTYPCB");
    if(cur == ""){
        formattedData = data+"%";
    } else if(cur == "-"){
        formattedData = "-";
    } else {
        formattedData = data;
    }
    return formattedData;
}
scwin.setPerNumFrF = function(data, formattedData, rowIndex, colIndex){
    let cur = dlt_out.getCellData(rowIndex, "CMFCTYPF");
    if(cur == ""){
        formattedData = data+"%";
    } else if(cur == "-"){
        formattedData = "-";
    } else {
        formattedData = data;
    }
    return formattedData;
}
*/
