scwin.btn_excel_onclick = function() {
    var grdName;
    var infoArr = [];
    var sheetName;
    var colCount;        

    grdName = "grd_list";

    com.downLoadExcel(eval(grdName), {
        fileName: "Commission Tariff Inquiry.xlsx",
        useDataFormat: true,
        startRowIndex : 0                                       // 시작 rowIndex를 꼭 넣어 주세요
    }, infoArr);
};
    scwin.trigger1_onclick = function() {
        grd_list.setTopRowIndex(1);
    }
    scwin.trigger2_onclick = function() {
        grd_list.setTopRowIndex(0);
    }

	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('grd_list_cell_1_23').innerText == '-';
	}
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('grd_list_cell_3_23').innerText == '-';
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grd_list_scrollY_div').scrollTop = 100");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
